mapper.select:
SELECT order_scope, order_value, content_hash, state_json::text AS state_json,
       version, observed_at, received_at
FROM iot_reported_group
WHERE device_id = #{deviceId} AND binding_generation = #{bindingGeneration}
  AND group_code = #{groupCode}

mapper.update:
UPDATE iot_reported_group
SET order_scope = #{orderScope}, order_value = #{orderValue}, content_hash = #{contentHash},
    state_json = CAST(#{stateJson} AS JSONB), observed_at = #{observedAt}, received_at = #{receivedAt},
    version = version + 1
WHERE device_id = #{deviceId} AND binding_generation = #{bindingGeneration}
  AND group_code = #{groupCode} AND version = #{expectedVersion}
